// encodeFieldsMap converts the JSON event representation into a DynamoDB map.
// UseNumber preserves integer and decimal values while translating JSON values
// to DynamoDB attributes.
func encodeFieldsMap(data []byte) (map[string]interface{}, error) {
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.UseNumber()
	var fields map[string]interface{}
	if err := decoder.Decode(&fields); err != nil {
		return nil, trace.Wrap(err)
	}
	if fields == nil {
		return nil, trace.BadParameter("event fields must be a JSON object")
	}
	var trailing interface{}
	if err := decoder.Decode(&trailing); err != io.EOF {
		if err == nil {
			return nil, trace.BadParameter("event fields contain more than one JSON value")
		}
		return nil, trace.Wrap(err)
	}

	dynamoFields := dynamoNumberValues(fields).(map[string]interface{})
	attributes, err := marshalMapPreservingEmptyCollections(dynamoFields)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	decoded := make(map[string]interface{}, len(attributes))
	for key, attribute := range attributes {
		value, err := attributeValueToJSON(attribute)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		decoded[key] = value
	}
	if !reflect.DeepEqual(normalizeJSONNumbers(fields), normalizeJSONNumbers(decoded)) {
		return nil, trace.BadParameter("event fields changed during DynamoDB map conversion")
	}
	return dynamoFields, nil
}

func marshalMapPreservingEmptyCollections(value interface{}) (map[string]*dynamodb.AttributeValue, error) {
	encoder := dynamodbattribute.NewEncoder(func(encoder *dynamodbattribute.Encoder) {
		encoder.EnableEmptyCollections = true
	})
	attribute, err := encoder.Encode(value)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if attribute == nil || attribute.M == nil {
		return map[string]*dynamodb.AttributeValue{}, nil
	}
	return attribute.M, nil
}

func marshalEvent(e event) (map[string]*dynamodb.AttributeValue, error) {
	return marshalMapPreservingEmptyCollections(e)
}

func dynamoNumberValues(value interface{}) interface{} {
	switch value := value.(type) {
	case json.Number:
		return dynamodbattribute.Number(value.String())
	case map[string]interface{}:
		converted := make(map[string]interface{}, len(value))
		for key, entry := range value {
			converted[key] = dynamoNumberValues(entry)
		}
		return converted
	case []interface{}:
		converted := make([]interface{}, len(value))
		for i, entry := range value {
			converted[i] = dynamoNumberValues(entry)
		}
		return converted
	default:
		return value
	}
}

func attributeValueToJSON(attribute *dynamodb.AttributeValue) (interface{}, error) {
	switch {
	case attribute == nil:
		return nil, nil
	case attribute.BOOL != nil:
		return aws.BoolValue(attribute.BOOL), nil
	case attribute.L != nil:
		values := make([]interface{}, len(attribute.L))
		for i, entry := range attribute.L {
			value, err := attributeValueToJSON(entry)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			values[i] = value
		}
		return values, nil
	case attribute.M != nil:
		values := make(map[string]interface{}, len(attribute.M))
		for key, entry := range attribute.M {
			value, err := attributeValueToJSON(entry)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			values[key] = value
		}
		return values, nil
	case attribute.N != nil:
		return json.Number(aws.StringValue(attribute.N)), nil
	case attribute.S != nil:
		return aws.StringValue(attribute.S), nil
	case attribute.NULL != nil:
		return nil, nil
	default:
		return nil, trace.BadParameter("unsupported DynamoDB attribute type in event fields")
	}
}

type normalizedJSONNumber string

func normalizeJSONNumbers(value interface{}) interface{} {
	switch value := value.(type) {
	case json.Number:
		return normalizedJSONNumber(canonicalJSONNumber(value.String()))
	case dynamodbattribute.Number:
		return normalizedJSONNumber(canonicalJSONNumber(value.String()))
	case map[string]interface{}:
		normalized := make(map[string]interface{}, len(value))
		for key, entry := range value {
			normalized[key] = normalizeJSONNumbers(entry)
		}
		return normalized
	case []interface{}:
		normalized := make([]interface{}, len(value))
		for i, entry := range value {
			normalized[i] = normalizeJSONNumbers(entry)
		}
		return normalized
	default:
		return value
	}
}

// canonicalJSONNumber produces an exact canonical decimal form, including
// equivalent representations such as 1, 1.0, and 10e-1.
func canonicalJSONNumber(value string) string {
	sign := ""
	if strings.HasPrefix(value, "-") {
		sign = "-"
		value = value[1:]
	}
	exponent := 0
	if i := strings.IndexAny(value, "eE"); i >= 0 {
		parsed, err := strconv.Atoi(value[i+1:])
		if err != nil {
			return sign + value
		}
		exponent = parsed
		value = value[:i]
	}
	decimalPlaces := 0
	if i := strings.IndexByte(value, '.'); i >= 0 {
		decimalPlaces = len(value) - i - 1
		value = value[:i] + value[i+1:]
	}
	exponent -= decimalPlaces
	value = strings.TrimLeft(value, "0")
	if value == "" {
		return "0"
	}
	for strings.HasSuffix(value, "0") {
		value = strings.TrimSuffix(value, "0")
		exponent++
	}
	return sign + value + "e" + strconv.Itoa(exponent)
}

