		EventIndex:     int64(eventIndex),
		EventType:      fields.GetString(events.EventType),
		EventNamespace: apidefaults.Namespace,
		CreatedAt:      created.Unix(),
		FieldsMap:      fieldsMap,
		CreatedAtDate:  created.Format(iso8601DateFormat),
	}
	l.setExpiry(&e)
	av, err := marshalEvent(e)
	if err != nil {
		return trace.Wrap(err)
	}
	input := dynamodb.PutItemInput{
		Item:      av,
		TableName: aws.String(l.Tablename),
	}
	_, err = l.svc.PutItem(&input)
	err = convertError(err)
	if err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func (l *Log) setExpiry(e *event) {
	if l.RetentionPeriod == 0 {
		return
	}
	e.Expires = aws.Int64(l.Clock.Now().UTC().Add(l.RetentionPeriod).Unix())
}

// PostSessionSlice sends chunks of recorded session to the event log
func (l *Log) PostSessionSlice(slice events.SessionSlice) error {
	var requests []*dynamodb.WriteRequest
	for _, chunk := range slice.Chunks {
		// if legacy event with no type or print event, skip it
		if chunk.EventType == events.SessionPrintEvent || chunk.EventType == "" {
			continue
		}
		fields, err := events.EventFromChunk(slice.SessionID, chunk)
		if err != nil {
			return trace.Wrap(err)
		}
		data, err := json.Marshal(fields)
		if err != nil {
			return trace.Wrap(err)
		}
		fieldsMap, err := encodeFieldsMap(data)
		if err != nil {
			return trace.Wrap(err)
		}

		timeAt := time.Unix(0, chunk.Time).In(time.UTC)

		event := event{
			SessionID:      slice.SessionID,
			EventNamespace: apidefaults.Namespace,
			EventType:      chunk.EventType,
			EventIndex:     chunk.EventIndex,
			CreatedAt:      timeAt.Unix(),
			FieldsMap:      fieldsMap,
			CreatedAtDate:  timeAt.Format(iso8601DateFormat),
		}
		l.setExpiry(&event)
		item, err := marshalEvent(event)
		if err != nil {
			return trace.Wrap(err)
		}
		requests = append(requests, &dynamodb.WriteRequest{
			PutRequest: &dynamodb.PutRequest{
				Item: item,
			},
		})
	}
	// no chunks to post (all chunks are print events)
	if len(requests) == 0 {
		return nil
	}
	input := dynamodb.BatchWriteItemInput{
		RequestItems: map[string][]*dynamodb.WriteRequest{
			l.Tablename: requests,
		},
	}
			FilterExpression: aws.String("attribute_not_exists(CreatedAtDate)"),
		}

		// Resume the scan at the end of the previous one.
		// This processes `DynamoBatchSize*maxMigrationWorkers` events at maximum
		// which is why we need to run this multiple times on the dataset.
		scanOut, err := l.svc.Scan(c)
		if err != nil {
			return trace.Wrap(convertError(err))
		}

		writeRequests := make([]*dynamodb.WriteRequest, 0, DynamoBatchSize*maxMigrationWorkers)

		// For every item processed by this scan iteration we generate a write request.
		for _, item := range scanOut.Items {
			// Extract the UTC timestamp integer of the event.
			timestampAttribute := item[keyCreatedAt]
			var timestampRaw int64
			err = dynamodbattribute.Unmarshal(timestampAttribute, &timestampRaw)
			if err != nil {
				return trace.Wrap(err)
			}

			// Convert the timestamp into a date string of format `yyyy-mm-dd`.
			timestamp := time.Unix(timestampRaw, 0)
			date := timestamp.Format(iso8601DateFormat)

			dateAttribute, err := dynamodbattribute.Marshal(date)
			if err != nil {
				return trace.Wrap(err)
			}

			item[keyDate] = dateAttribute

			wr := &dynamodb.WriteRequest{
				PutRequest: &dynamodb.PutRequest{
					Item: item,
				},
			}

			writeRequests = append(writeRequests, wr)
		}

		for len(writeRequests) > 0 {
			var top int
			if len(writeRequests) > DynamoBatchSize {
				top = DynamoBatchSize
			} else {
				top = len(writeRequests)
			}

			// We need to make a copy of the slice here so it doesn't get changed later due to subslicing.
			batch := append(make([]*dynamodb.WriteRequest, 0, DynamoBatchSize), writeRequests[:top]...)
			writeRequests = writeRequests[top:]

			// Don't exceed maximum workers.
			for workerCounter.Load() >= maxMigrationWorkers {
				select {
				case <-time.After(time.Millisecond * 50):
				case <-ctx.Done():
					return trace.Wrap(ctx.Err())
				}
			}

			workerCounter.Add(1)
			workerBarrier.Add(1)
			go func() {
				defer workerCounter.Sub(1)
				defer workerBarrier.Done()
				amountProcessed := len(batch)

				if err := l.uploadBatch(batch); err != nil {
					workerErrors <- trace.Wrap(err)
					return
				}

				total := totalProcessed.Add(int32(amountProcessed))
				log.Infof("Migrated %d total events to 6.2 format...", total)
			}()
		}

		// Setting the startKey to the last evaluated key of the previous scan so that
		// the next scan doesn't return processed events.
		startKey = scanOut.LastEvaluatedKey

		// If the `LastEvaluatedKey` field is not set we have finished scanning
		// the entire dataset and we can now break out of the loop.
		if scanOut.LastEvaluatedKey == nil {
			break
		}
	}

	// Wait until all upload tasks finish.
	workerBarrier.Wait()

	// Check for worker errors and escalate if found.
	select {
	case err := <-workerErrors:
		return trace.Wrap(err)
	default:
	}

	return nil
}

type fieldsMapMigrationCheckpoint struct {
	LastEvaluatedKey map[string]*dynamodb.AttributeValue `json:"last_evaluated_key,omitempty"`
	Complete         bool                                `json:"complete,omitempty"`
}

func (l *Log) fieldsMapMigrationFlagKey() []byte {
	return backend.FlagKey("dynamoEvents", "fieldsMapMigration", l.Tablename)
}

func eventIndexFromItem(item map[string]*dynamodb.AttributeValue) int64 {
	attribute := item[keyEventIndex]
	if attribute == nil || attribute.N == nil {
		return 0
	}
	index, _ := strconv.ParseInt(aws.StringValue(attribute.N), 10, 64)
	return index
}

func (l *Log) migrateFieldsMapWithRetry(ctx context.Context) {
	for {
		err := backend.RunWhileLocked(ctx, l.backend, fieldsMapMigrationLock, rfd24MigrationLockTTL, func(ctx context.Context) error {
			return l.migrateFieldsMap(ctx)
		})
		if err == nil {
			return
		}

		delay := utils.HalfJitter(time.Minute)
		log.WithError(err).Errorf("DynamoDB FieldsMap migration failed, retrying in %f seconds", delay.Seconds())
		select {
		case <-time.After(delay):
		case <-ctx.Done():
			log.WithError(ctx.Err()).Error("DynamoDB FieldsMap migration cancelled")
			return
		}
	}
}

// migrateFieldsMap converts legacy JSON Fields strings to the native FieldsMap
// attribute. Each fully written scan page advances a durable checkpoint, making
// retries safe after interruption. The caller must hold fieldsMapMigrationLock.
func (l *Log) migrateFieldsMap(ctx context.Context) error {
	checkpointKey := l.fieldsMapMigrationFlagKey()
	checkpoint := fieldsMapMigrationCheckpoint{}
	checkpointItem, err := l.backend.Get(ctx, checkpointKey)
	if err != nil && !trace.IsNotFound(err) {
		return trace.Wrap(err)
	}
	if err == nil {
		if err := json.Unmarshal(checkpointItem.Value, &checkpoint); err != nil {
			return trace.WrapWithMessage(err, "failed to decode FieldsMap migration checkpoint")
		}
	}
	if checkpoint.Complete {
		log.Info("DynamoDB FieldsMap migration is already complete")
		return nil
	}

	var totalMigrated int64
	for {
		select {
		case <-ctx.Done():
			return trace.Wrap(ctx.Err())
		default:
		}

		scanOut, err := l.svc.ScanWithContext(ctx, &dynamodb.ScanInput{
			ExclusiveStartKey: checkpoint.LastEvaluatedKey,
			ConsistentRead:    aws.Bool(true),
			Limit:             aws.Int64(DynamoBatchSize * maxMigrationWorkers),
			TableName:         aws.String(l.Tablename),
			FilterExpression:  aws.String("attribute_exists(#fields) AND attribute_not_exists(#fieldsMap)"),
			ExpressionAttributeNames: map[string]*string{
				"#fields":    aws.String(keyFields),
				"#fieldsMap": aws.String(keyFieldsMap),
			},
		})
		if err != nil {
			return trace.Wrap(convertError(err))
		}

		writeRequests := make([]*dynamodb.WriteRequest, 0, len(scanOut.Items))
		for _, item := range scanOut.Items {
			legacyFields := item[keyFields]
			if legacyFields == nil || legacyFields.S == nil {
				err := trace.BadParameter("legacy Fields attribute is missing or is not a string")
				l.WithFields(log.Fields{
					"SessionID":  aws.StringValue(item[keySessionID].S),
					"EventIndex": eventIndexFromItem(item),
				}).WithError(err).Error("Failed to migrate DynamoDB event Fields")
				return err
			}
			fieldsMap, err := encodeFieldsMap([]byte(aws.StringValue(legacyFields.S)))
			if err != nil {
				l.WithFields(log.Fields{
					"SessionID":  aws.StringValue(item[keySessionID].S),
					"EventIndex": eventIndexFromItem(item),
				}).WithError(err).Error("Failed to convert DynamoDB event Fields to FieldsMap")
				return trace.WrapWithMessage(err, "failed converting event SessionID=%q EventIndex=%d", aws.StringValue(item[keySessionID].S), eventIndexFromItem(item))
			}
			attributes, err := marshalMapPreservingEmptyCollections(fieldsMap)
			if err != nil {
				return trace.WrapWithMessage(err, "failed encoding FieldsMap for event SessionID=%q EventIndex=%d", aws.StringValue(item[keySessionID].S), eventIndexFromItem(item))
			}
			item[keyFieldsMap] = &dynamodb.AttributeValue{M: attributes}
			delete(item, keyFields)
			writeRequests = append(writeRequests, &dynamodb.WriteRequest{
				PutRequest: &dynamodb.PutRequest{Item: item},
			})
		}

		batches := make([][]*dynamodb.WriteRequest, 0, (len(writeRequests)+DynamoBatchSize-1)/DynamoBatchSize)
		for len(writeRequests) > 0 {
			top := DynamoBatchSize
			if len(writeRequests) < top {
				top = len(writeRequests)
			}
			batches = append(batches, append([]*dynamodb.WriteRequest(nil), writeRequests[:top]...))
			writeRequests = writeRequests[top:]
		}

		workerErrors := make(chan error, len(batches))
		var workers sync.WaitGroup
		var migrated atomic.Int32
		for _, batch := range batches {
			batch := batch
			workers.Add(1)
			go func() {
				defer workers.Done()
				if err := l.uploadFieldsMapBatch(ctx, batch); err != nil {
					first := batch[0].PutRequest.Item
					workerErrors <- trace.WrapWithMessage(err, "failed writing FieldsMap batch starting at SessionID=%q EventIndex=%d", aws.StringValue(first[keySessionID].S), eventIndexFromItem(first))
					return
				}
				current := migrated.Add(int32(len(batch)))
				l.Infof("Migrated %d events to FieldsMap for table %s", totalMigrated+int64(current), l.Tablename)
			}()
		}
		workers.Wait()
		close(workerErrors)
		for err := range workerErrors {
			return trace.Wrap(err)
		}
		totalMigrated += int64(len(scanOut.Items))

		checkpoint.LastEvaluatedKey = scanOut.LastEvaluatedKey
		checkpoint.Complete = scanOut.LastEvaluatedKey == nil
		checkpointData, err := json.Marshal(checkpoint)
		if err != nil {
			return trace.Wrap(err)
		}
		if _, err := l.backend.Put(ctx, backend.Item{Key: checkpointKey, Value: checkpointData}); err != nil {
			return trace.WrapWithMessage(err, "failed to save FieldsMap migration checkpoint")
		}
		if checkpoint.Complete {
			log.Infof("Completed DynamoDB FieldsMap migration for table %s; migrated %d events", l.Tablename, totalMigrated)
			return nil
		}
	}
}

func (l *Log) uploadFieldsMapBatch(ctx context.Context, writeRequests []*dynamodb.WriteRequest) error {
	for len(writeRequests) > 0 {
		out, err := l.svc.BatchWriteItemWithContext(ctx, &dynamodb.BatchWriteItemInput{
			RequestItems: map[string][]*dynamodb.WriteRequest{l.Tablename: writeRequests},
		})
		if err != nil {
			return trace.Wrap(convertError(err))
		}
		writeRequests = out.UnprocessedItems[l.Tablename]
		if len(writeRequests) == 0 {
			return nil
		}
		select {
		case <-ctx.Done():
			return trace.Wrap(ctx.Err())
		case <-time.After(100 * time.Millisecond):
		}
	}
	return nil
}

